void configure_pb4_ft_c_input(void)
{
    /* 1. Enable PWR peripheral clock and disable UCPD dead battery pull-down */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    PWR->CR3 |= PWR_CR3_UCPD_DBDIS;

    /* 2. Enable GPIOB clock */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN;

    /* 3. Configure PB4 as digital input (MODER = 00b) */
    GPIOB->MODER &= ~(GPIO_MODER_MODE4_Msk);

    /* 4. Disable pull-up / pull-down (PUPDR = 00b, floating) */
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD4_Msk);
}
```

